function movementTextKey(value){return String(value||"").trim().toLocaleLowerCase("tr-TR")}
function movementTextParts(value){return String(value||"").split("•").map(part=>part.trim()).filter(Boolean)}
function uniqueMovementText(parts){const seen=new Set;return parts.filter(part=>{const key=movementTextKey(part);if(!key||seen.has(key))return false;seen.add(key);return true})}
function movementDisplayText(m,kind,person,description){const personKey=movementTextKey(person),kindKey=movementTextKey(kind),descriptionParts=movementTextParts(description).filter(part=>{const key=movementTextKey(part);return key!==personKey&&key!==kindKey}),title=uniqueMovementText([kind,...descriptionParts]).join(" • ")||kind,detail=uniqueMovementText([person,formatBusinessDate(m.businessDate||selectedDate),formatTime(number(m.updatedAtMs)||number(m.createdAtMs))]).join(" • ");return{title,detail}}
function simpleMovementMarkup(m,editable){const automatic=m.automatic===true,transfer=m.type==="transfer",actions=!automatic&&editable?movementButtons(m.id):automatic?'<span class="simple-record-badge"><i class="fa-solid fa-lock"></i> Otomatik</span>':'<span class="simple-record-badge readonly"><i class="fa-solid fa-eye"></i> Salt okunur</span>',kind=transfer?(m.toAccount==="creditCard"?"Kredi Kartı Ödemesi":m.toAccount==="bankLoan"?"Banka Kredisi Taksit Ödemesi":"Hesap Aktarımı"):m.category||typeName(m.type),person=userDisplayName(m.createdBy),adisyonIncome=m.automatic&&m.type==="income"&&(m.category==="Gün Sonu"||m.source==="pos-instant"),description=m.source==="sale-user-display"?m.description:adisyonIncome?"Adisyondan Gelen":m.description||kind,display=movementDisplayText(m,kind,person,description),payment=m.source==="rounding-note"?"Kasadan düşmez":accountText(m),prefix=transfer?"↔":m.type==="expense"?"−":"+";return`<article class="simple-movement-row ${m.type}"><div class="simple-movement-copy"><strong>${esc(display.title)}</strong><small>${esc(display.detail)}</small></div><span class="simple-payment-method">${esc(payment||"—")}</span><b class="simple-movement-amount">${prefix} ${money(m.amount)}</b><div class="simple-movement-actions">${actions}</div></article>`}
function movementButtons(id){const savings=manualMovements.find(x=>x.id===id)?.source==="savings";if(savings&&!savingsOwner())return'<span class="simple-record-badge readonly">Salt okunur</span>';return`<button type="button" data-edit="${esc(id)}"><i class="fa-solid fa-pen"></i><span>Düzelt</span></button><button type="button" class="delete" data-delete="${esc(id)}"><i class="fa-solid fa-trash"></i><span>${savings?"İptal Et":"Sil"}</span></button>`}
