function accountSummaryConfig(view){const configs={"cash-all":{title:"Nakit Kasa Hareketleri",account:"cash",mode:"all",label:"Güncel nakit kasa",note:"Nakit giriş, çıkış ve hesap aktarımları birlikte görünür."},"bank-all":{title:"Banka Hesabı Hareketleri",account:"bank",mode:"all",label:"Güncel banka bakiyesi",note:"Bankaya giren, bankadan çıkan ve hesap aktarımları birlikte görünür."},"card-all":{title:"POS Hesabı Hareketleri",account:"card",mode:"all",label:"Güncel POS hesabı",note:"Kart / POS gelirleri ve hesaba ait aktarımlar birlikte görünür."},"cash-income":{title:"Nakit Gelir Hareketleri",account:"cash",mode:"income",label:"İlgili ay nakit gelir",note:"İlgili ayda adisyondan ve diğer kaynaklardan gelen nakit gelirler görünür."},"bank-income":{title:"Havale Gelir Hareketleri",account:"bank",mode:"income",label:"İlgili ay banka geliri",note:"İlgili ayda bankaya gelen adisyon, cari ve diğer gelirler görünür."},"card-income":{title:"Kart / POS Gelir Hareketleri",account:"card",mode:"income",label:"İlgili ay kart geliri",note:"İlgili ayda çekilen kart / POS gelirleri görünür."},"cash-expense":{title:"Nakit Gider Hareketleri",account:"cash",mode:"expense",label:"İlgili ay nakit gider",note:"İlgili ayda nakit kasadan yapılan giderler görünür."},"bank-expense":{title:"Bankadan Çıkan Hareketler",account:"bank",mode:"outgoing",label:"İlgili ay bankadan çıkan",note:"İlgili ayın banka ödemeleri ve bankadan yapılan hesap aktarımları birlikte görünür."},"credit-expense":{title:"Kredi Kartı Harcamaları",account:"creditCard",mode:"expense",label:"İlgili ay kredi kartı harcaması",note:"İlgili ayda kredi kartıyla yapılan harcamalar açıklama ve tarihleriyle görünür."}};return configs[view]||configs["bank-all"]}
function accountSummaryRows(view){const cfg=accountSummaryConfig(view);return monthlyDisplayRows().filter(m=>{if(cfg.mode==="income")return m.type==="income"&&m.account===cfg.account;if(cfg.mode==="expense")return m.type==="expense"&&m.account===cfg.account;if(cfg.mode==="outgoing")return m.type==="expense"&&m.account===cfg.account||m.type==="transfer"&&m.fromAccount===cfg.account;return m.type==="transfer"?(m.fromAccount===cfg.account||m.toAccount===cfg.account):m.account===cfg.account})}
function accountSummaryValue(cfg,rows){if(cfg.mode!=="all")return rows.reduce((sum,m)=>sum+number(m.amount),0);const b=accountBalancesForDate(today());return cfg.account==="cash"?b.cash:cfg.account==="bank"?b.bank:b.card}
function renderAccountSummary(){const cfg=accountSummaryConfig(accountSummaryView),rows=accountSummaryRows(accountSummaryView),month=selectedDate.slice(0,7);$("bankSummaryTitle").textContent=cfg.title;$("bankSummaryDate").textContent=monthName(month);$("bankSummaryBalanceLabel").textContent=cfg.label;$("bankSummaryBalance").textContent=money(accountSummaryValue(cfg,rows));$("bankSummaryNote").textContent=cfg.note;$("bankSummaryList").innerHTML=rows.map(m=>accountMovementMarkup(m,cfg.account)).join("");$("bankSummaryEmpty").hidden=rows.length>0;$("bankSummaryEmpty").textContent=`${monthName(month)} içinde bu türde hareket bulunmuyor.`}
function accountMovementMarkup(m,account){const transfer=m.type==="transfer",outgoing=m.type==="expense"||transfer&&m.fromAccount===account,direction=outgoing?"−":"+",adisyonIncome=m.automatic===true&&m.type==="income"&&(m.category==="Gün Sonu"||m.source==="pos-instant"),kind=transfer?"Hesap aktarımı":m.type==="expense"?"Gider":m.category==="Cari Tahsilatı"?"Cari tahsilatı":adisyonIncome?"Adisyondan gelen":"Gelir",person=userDisplayName(m.createdBy),time=formatTime(number(m.updatedAtMs)||number(m.createdAtMs)),title=m.source==="sale-user-display"?m.description:adisyonIncome?"Adisyondan Gelen":[m.description||m.category||kind,person].filter(Boolean).join(" • "),details=[kind,m.category||"",person,transfer?accountText(m):accountText(m),formatBusinessDate(m.businessDate||today()),time].filter(Boolean),detail=details.filter((value,index)=>details.findIndex(item=>String(item).toLocaleLowerCase("tr-TR")===String(value).toLocaleLowerCase("tr-TR"))===index).join(" • ");return`<article class="bank-movement-row ${outgoing?"outgoing":"incoming"}"><div class="bank-movement-copy"><strong>${esc(title)}</strong><small>${esc(detail)}</small></div><b>${direction} ${money(m.amount)}</b></article>`}
function dayTotals(rows){return rows.reduce((t,m)=>{const value=number(m.amount);if(m.type==="income"){t.income+=value;if(m.account==="cash")t.cashIncome+=value;if(m.account==="bank")t.bankIncome+=value;if(m.account==="card")t.cardIncome+=value;if(m.automatic===true){if(m.account==="cash")t.automaticCashIncome+=value;if(m.account==="bank")t.automaticBankIncome+=value;if(m.account==="card")t.automaticCardIncome+=value}else t.manualIncome+=value}if(m.type==="expense"){t.expense+=value;if(m.account==="cash")t.cashExpense+=value;if(m.account==="bank")t.bankExpense+=value;if(m.account==="creditCard")t.cardExpense+=value;if(m.category==="Eksi Yuvarlama")t.roundingExpense+=value}if(m.type==="transfer"&&m.fromAccount==="bank")t.bankTransferOut+=value;return t},{income:0,cashIncome:0,bankIncome:0,cardIncome:0,expense:0,cashExpense:0,bankExpense:0,bankTransferOut:0,cardExpense:0,automaticCashIncome:0,automaticBankIncome:0,automaticCardIncome:0,roundingExpense:0,manualIncome:0})}

