async function saveMovement(e){e.preventDefault();if(!canEditSelectedDate())return toast(selectedDate===today()?"Bu finans günü kapalı; kayıt kaydedilemez.":"Geçmiş gün kayıtları değiştirilemez.");const type=$("movementType").value,amount=number($("amount").value),data={type,amount,account:type==="transfer"?"":$("account").value,fromAccount:type==="transfer"?$("fromAccount").value:"",toAccount:type==="transfer"?$("toAccount").value:"",category:type==="transfer"?$("transferCategory").value:$("category").value,description:$("description").value.trim(),businessDate:selectedDate,automatic:false,source:"manual",updatedAtMs:Date.now(),updatedAt:serverTimestamp()};if(type!=="transfer"){const item=categoryItems(type).find(x=>x.id===$("category").value),group=groupForCategory(type,item);if(!item||!group||!group.active)return toast("Kategori seçin.");data.category=item.name;data.categoryId=item.id;data.groupId=group.id;data.groupName=group.name}else{delete data.categoryId;delete data.groupId;delete data.groupName}if(amount<=0)return toast("Geçerli bir tutar girin.");if(type!=="transfer"&&!data.category)return toast("Önce Kasa Ayarları'ndan bir kategori ekleyin.");if(!data.description)return toast("İşlem için kısa bir açıklama girin.");if(type==="transfer"&&data.toAccount==="bankLoan"){if(!["cash","bank","card"].includes(data.fromAccount))return toast("Kredi taksiti için nakit, banka veya POS hesabı seçin.");data.category="Banka Kredisi Taksit Ödemesi"}if(type==="transfer"&&data.fromAccount===data.toAccount)return toast("Gönderen ve alan hesap farklı olmalıdır.");try{const id=$("movementId").value;if(id)await updateDoc(doc(db,"adminCashMovements",id),{...data,updatedBy:auth.currentUser.uid});else await setDoc(doc(movementsCol),{...data,createdAtMs:Date.now(),createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});$("movementDialog").close();toast(id?"Hareket güncellendi.":"Hareket kaydedildi.")}catch(error){console.error(error);toast("Hareket kaydedilemedi.")}}
function movementAction(e){const edit=e.target.closest("[data-edit]"),remove=e.target.closest("[data-delete]");if(!edit&&!remove)return;const savings=manualMovements.find(x=>x.id===(edit?.dataset.edit||remove?.dataset.delete)&&x.source==="savings");if(savings&&remove){openSavingsMovement({operationId:savings.transactionId,businessDate:selectedDate,cancel:true}).catch(e=>toast(savingsError(e)));return}if(!canEditSelectedDate())return toast(selectedDate===today()?"Bu finans günü kapalı; kayıtlar değiştirilemez.":"Geçmiş gün kayıtları değiştirilemez.");if($("bankSummaryDialog").open)$("bankSummaryDialog").close();if(edit){const m=manualMovements.find(x=>x.id===edit.dataset.edit);if(m)openDialog(m.type,m)}if(remove){pendingDeleteId=remove.dataset.delete;$("deleteDialog").showModal()}}
async function deleteMovement(){if(!pendingDeleteId)return;const savings=manualMovements.find(x=>x.id===pendingDeleteId&&x.source==="savings");if(savings){$("deleteDialog").close();pendingDeleteId="";try{await openSavingsMovement({operationId:savings.transactionId,businessDate:selectedDate,cancel:true})}catch(e){toast(savingsError(e))}return}if(!canEditSelectedDate())return toast(selectedDate===today()?"Bu finans günü kapalı; kayıt silinemez.":"Geçmiş gün kayıtları silinemez.");try{await deleteDoc(doc(db,"adminCashMovements",pendingDeleteId));pendingDeleteId="";$("deleteDialog").close();toast("Hareket silindi.")}catch(error){console.error(error);toast("Hareket silinemedi.")}}

