async function reminderAction(e){const paid=e.target.closest("[data-reminder-paid]"),restore=e.target.closest("[data-reminder-restore]"),remove=e.target.closest("[data-reminder-delete]");if(paid)return openReminderPaidConfirm(paid.dataset.reminderPaid);try{if(restore)await updateDoc(doc(db,"adminPaymentReminders",restore.dataset.reminderRestore),{status:"pending",updatedAtMs:Date.now(),updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});if(remove)await deleteDoc(doc(db,"adminPaymentReminders",remove.dataset.reminderDelete));if(restore)toast("Ödeme tekrar bekleyenlere alındı.");if(remove)toast("Hatırlatma silindi.")}catch(error){console.error(error);toast("Hatırlatma güncellenemedi.")}}
