function pendingReminders(){return reminders.filter(x=>x.status!=="paid").sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate)))}
function renderReminders(){const target=$("reminderList");if(!target)return;const items=pendingReminders(),paidItems=reminders.filter(x=>x.status==="paid").sort((a,b)=>number(b.paidAtMs)-number(a.paidAtMs));target.innerHTML=items.map(x=>{const overdue=x.dueDate<today();return`<article class="reminder-row ${overdue?"is-overdue":""}"><i class="fa-solid ${overdue?"fa-triangle-exclamation":"fa-calendar-day"}"></i><div><strong>${esc(x.name)}</strong><small>${formatBusinessDate(x.dueDate)}${number(x.amount)>0?` • ${money(x.amount)}`:""}${overdue?" • Gecikti":""}</small></div><div class="reminder-actions"><button class="paid" data-reminder-paid="${esc(x.id)}"><i class="fa-solid fa-check"></i> Ödendi</button><button data-reminder-delete="${esc(x.id)}"><i class="fa-solid fa-trash"></i></button></div></article>`}).join("");$("reminderEmpty").hidden=items.length>0;const history=$("paidReminderList"),historyEmpty=$("paidReminderEmpty");if(history)history.innerHTML=paidItems.map(x=>`<article class="reminder-row is-paid"><i class="fa-solid fa-circle-check"></i><div><strong>${esc(x.name)}</strong><small>${formatBusinessDate(x.dueDate)}${number(x.amount)>0?` • ${money(x.amount)}`:""} • Ödendi</small></div><div class="reminder-actions"><button data-reminder-restore="${esc(x.id)}" title="Tekrar bekleyenlere al"><i class="fa-solid fa-rotate-left"></i> Bekleyene Al</button><button data-reminder-delete="${esc(x.id)}" title="Geçmişten sil"><i class="fa-solid fa-trash"></i></button></div></article>`).join("");if(historyEmpty)historyEmpty.hidden=paidItems.length>0}
function renderReminderBadge(){const items=pendingReminders(),overdue=items.filter(x=>x.dueDate<today()).length;$("reminderBadge").textContent=overdue?`${overdue} gecikmiş ödeme`:items.length?`${items.length} bekleyen ödeme`:"Yaklaşan ödeme yok"}

