function openSettingsPanel(name){const dialogs={opening:"openingSettingsDialog",income:"incomeSettingsDialog",expense:"expenseSettingsDialog"},panel=name==="transfer"?"expense":name,target=$(dialogs[panel]);if(!target)return;$("settingsDialog").close();categoryPanelMode=name==="income"||name==="expense"||name==="transfer"?name:"";if(categoryPanelMode){target.classList.toggle("transfer-mode",name==="transfer");const title=target.querySelector("h2"),form=target.querySelector("[data-category-form]"),input=form?.querySelector("input"),list=$("expenseCategoryList");if(name==="transfer"){title.textContent="Aktarım Kategorileri";form.dataset.categoryForm="transfer";form.querySelector("[data-category-group]").disabled=true;input.placeholder="Yeni aktarım kategorisi"}else if(name==="expense"){title.textContent="Giderler";form.dataset.categoryForm="expense";form.querySelector("[data-category-group]").disabled=false;input.placeholder="Yeni gider kategorisi";list.id="expenseCategoryList"}else{title.textContent="Gelirler";form.dataset.categoryForm="income";input.placeholder="Yeni gelir kategorisi"}renderCategoryList(name)}else renderSettings();target.showModal();if(categoryPanelMode)setTimeout(()=>$(categoryPanelMode==="income"?"incomeCategoryList":"expenseCategoryList").focus({preventScroll:true}),60)}
function returnToSettings(e){e?.preventDefault();if(categoryPanelMode==="transfer"){const dialog=$("expenseSettingsDialog"),title=dialog.querySelector("h2"),form=dialog.querySelector("[data-category-form]"),input=form.querySelector("input");title.textContent="Giderler";form.dataset.categoryForm="expense";form.querySelector("[data-category-group]").disabled=false;dialog.classList.remove("transfer-mode");input.placeholder="Yeni gider kategorisi"}categoryPanelMode="";closeSettingsPanels();renderSettings();$("settingsDialog").showModal()}
function closeSettingsPanels(){["openingSettingsDialog","incomeSettingsDialog","expenseSettingsDialog","transferSettingsDialog"].forEach(id=>{const dialog=$(id);if(dialog?.open)dialog.close()})}
function renderSettings(){$("openingCash").value=settings.openingCash;$('openingBank').value=settings.openingBank;$('openingCard').value=settings.openingCard;$('openingCardDebt').value=settings.openingCardDebt;renderCategoryList("income");if(categoryPanelMode!=="transfer")renderCategoryList("expense")}
function renderCategoryList(type){const target=$(type==="income"?"incomeCategoryList":"expenseCategoryList"),items=categoryItems(type);if(type!=="transfer"){const groups=groupItems(type),select=document.querySelector(`[data-category-group="${type}"]`),prior=select.value;select.innerHTML=groups.filter(g=>g.active).map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join("");if([...select.options].some(o=>o.value===prior))select.value=prior;$(type+"GroupList").innerHTML=groups.map(g=>`<div class="cash-group-chip ${g.active?"":"is-passive"}"><input maxlength="60" value="${esc(g.name)}" data-group-name="${esc(g.id)}" data-type="${type}" ${g.id===`${type}-legacy`?"readonly":""}><button type="button" data-group-toggle="${esc(g.id)}" data-type="${type}" ${g.id===`${type}-legacy`?"disabled":""}>${g.active?"Pasife Al":"Aktif Et"}</button><button type="button" data-group-delete="${esc(g.id)}" data-type="${type}" ${g.id===`${type}-legacy`?"disabled":""} aria-label="Grubu sil"><i class="fa-solid fa-trash"></i></button></div>`).join("")}
 target.innerHTML=items.map((x,i)=>`<article class="category-row ${x.active?'':'is-passive'}"><input value="${esc(x.name)}" maxlength="60" data-category-name="${esc(x.id)}" data-type="${type}">${type!=="transfer"?`<select data-category-assign="${esc(x.id)}" data-type="${type}" aria-label="Grup seç">${groupItems(type).map(g=>`<option value="${esc(g.id)}" ${groupForCategory(type,x).id===g.id?'selected':''}>${esc(g.name)}</option>`).join("")}</select>`:""}<div><button data-category-move="up" data-id="${esc(x.id)}" data-type="${type}" ${i===0?'disabled':''}><i class="fa-solid fa-chevron-up"></i></button><button data-category-move="down" data-id="${esc(x.id)}" data-type="${type}" ${i===items.length-1?'disabled':''}><i class="fa-solid fa-chevron-down"></i></button><button data-category-toggle="${esc(x.id)}" data-type="${type}">${x.active?'Pasife Al':'Aktif Et'}</button>${type!=="transfer"?`<button data-category-delete="${esc(x.id)}" data-type="${type}" aria-label="Kategoriyi sil"><i class="fa-solid fa-trash"></i></button>`:""}</div></article>`).join("")}
function categoryGroupChange(e){const select=e.target.closest("[data-category-assign]");if(!select)return;const type=select.dataset.type,items=categoryItems(type).map(x=>({...x})),item=items.find(x=>x.id===select.dataset.categoryAssign);if(!item)return;item.groupId=select.value;saveCategories(type,items)}
async function addGroup(e){e.preventDefault();const type=e.currentTarget.dataset.groupForm,input=e.currentTarget.querySelector("input"),name=input.value.trim(),groups=groupItems(type);if(!name)return;if(groups.some(g=>g.name.toLocaleLowerCase("tr-TR")===name.toLocaleLowerCase("tr-TR")))return toast("Bu grup zaten var.");await saveGroups(type,[...groups,{id:`${type}-group-${Date.now()}`,name,active:true}]);input.value=""}
async function groupAction(e){const button=e.target.closest("[data-group-toggle],[data-group-delete]");if(!button)return;const type=button.dataset.type,id=button.dataset.groupToggle||button.dataset.groupDelete,groups=groupItems(type).map(g=>({...g})),group=groups.find(g=>g.id===id);if(!group||id===`${type}-legacy`)return;if(button.dataset.groupToggle){group.active=!group.active;await saveGroups(type,groups);return}if(categoryItems(type).some(x=>groupForCategory(type,x).id===id)||manualMovements.some(m=>m.type===type&&m.groupId===id))return toast("Bu grupta kayıt var. Önce kategorileri taşıyın; geçmiş işlemler için grubu pasife alın.");askCategoryDelete({type,id,kind:"group",name:group.name})}
async function groupChange(e){const input=e.target.closest("[data-group-name]");if(!input||input.readOnly)return;const type=input.dataset.type,name=input.value.trim(),groups=groupItems(type).map(g=>({...g}));if(!name||groups.some(g=>g.id!==input.dataset.groupName&&g.name.toLocaleLowerCase("tr-TR")===name.toLocaleLowerCase("tr-TR")))return renderSettings();groups.find(g=>g.id===input.dataset.groupName).name=name;await saveGroups(type,groups)}
function askCategoryDelete(item){pendingCategoryDelete=item;$("categoryDeleteText").textContent=`${item.name} silinecek. Bu işlem geri alınamaz.`;$("categoryDeleteDialog").showModal()}
async function confirmCategoryDelete(){const item=pendingCategoryDelete;if(!item)return;const list=item.kind==="group"?groupItems(item.type):categoryItems(item.type);if(item.kind==="group"&&categoryItems(item.type).some(x=>groupForCategory(item.type,x).id===item.id))return toast("Grubun kategorileri var.");if(item.kind==="category"&&manualMovements.some(m=>m.type===item.type&&(m.categoryId===item.id||m.category===item.name||(item.aliases||[]).includes(m.category))))return toast("Bu kategori kullanılmış. Silmek yerine pasife alın.");const next=list.filter(x=>x.id!==item.id);if(item.kind==="group")await saveGroups(item.type,next);else await saveCategories(item.type,next);$("categoryDeleteDialog").close();pendingCategoryDelete=null}
async function saveGroups(type,groups){try{await setDoc(settingsRef,{[type+"Groups"]:groups.filter(g=>g.id!==`${type}-legacy`),updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid},{merge:true});toast("Gruplar güncellendi.")}catch(error){console.error(error);toast("Gruplar güncellenemedi.")}}

function categoryListKeys(e){if(e.target!==this)return;const steps={ArrowDown:51,ArrowUp:-51,PageDown:this.clientHeight,PageUp:-this.clientHeight};if(e.key in steps){e.preventDefault();this.scrollBy({top:steps[e.key],behavior:"smooth"})}else if(e.key==="Home"){e.preventDefault();this.scrollTo({top:0,behavior:"smooth"})}else if(e.key==="End"){e.preventDefault();this.scrollTo({top:this.scrollHeight,behavior:"smooth"})}}
async function saveOpeningBalances(e){e.preventDefault();try{await setDoc(settingsRef,{startDate:FINANCE_START_DATE,financeV3StartDate:FINANCE_START_DATE,financeV3Configured:true,legacyOpeningCash:settings.legacyOpeningCash,legacyOpeningBank:settings.legacyOpeningBank,legacyOpeningCard:settings.legacyOpeningCard,financeV3OpeningCash:number($("openingCash").value),financeV3OpeningBank:number($("openingBank").value),financeV3OpeningCard:number($("openingCard").value),financeV3OpeningCardDebt:number($("openingCardDebt").value),updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid},{merge:true});toast("Başlangıç bakiyeleri kaydedildi.");returnToSettings()}catch(error){console.error(error);toast("Başlangıç bakiyeleri kaydedilemedi.")}}
async function addCategory(e){e.preventDefault();const type=e.currentTarget.dataset.categoryForm,input=e.currentTarget.querySelector("input"),name=input.value.trim();if(!name)return;const items=[...(categoryItems(type))];if(items.some(x=>x.name.toLocaleLowerCase("tr-TR")===name.toLocaleLowerCase("tr-TR")))return toast("Bu kategori zaten bulunuyor.");items.push({id:`${type}-${Date.now()}`,name,active:true,groupId:type==="transfer"?"":document.querySelector(`[data-category-group="${type}"]`).value});await saveCategories(type,items);input.value=""}
async function categoryAction(e){const nameInput=e.target.closest("[data-category-name]"),toggle=e.target.closest("[data-category-toggle]"),move=e.target.closest("[data-category-move]");if(nameInput&&e.type==="click")return;const remove=e.target.closest("[data-category-delete]");if(remove){const type=remove.dataset.type,item=categoryItems(type).find(x=>x.id===remove.dataset.categoryDelete);if(manualMovements.some(m=>m.type===type&&(m.categoryId===item?.id||m.category===item?.name||(item?.aliases||[]).includes(m.category))))return toast("Bu kategori kullanılmış. Silmek yerine pasife alın.");if(item)askCategoryDelete({type,id:item.id,kind:"category",name:item.name});return}if(toggle){const type=toggle.dataset.type,items=[...(categoryItems(type))],item=items.find(x=>x.id===toggle.dataset.categoryToggle);if(item)item.active=!item.active;await saveCategories(type,items)}if(move){const type=move.dataset.type,items=[...(categoryItems(type))],i=items.findIndex(x=>x.id===move.dataset.id),j=move.dataset.categoryMove==="up"?i-1:i+1;if(i>=0&&j>=0&&j<items.length)[items[i],items[j]]=[items[j],items[i]];await saveCategories(type,items)}}
$("incomeCategoryList").onchange=$("expenseCategoryList").onchange=$("transferCategoryList").onchange=async e=>{const input=e.target.closest("[data-category-name]");if(!input)return;const name=input.value.trim();if(!name)return renderSettings();const type=input.dataset.type,items=[...(categoryItems(type))],item=items.find(x=>x.id===input.dataset.categoryName);if(item){if(item.name!==name)item.aliases=[...new Set([...(item.aliases||[]),item.name])];item.name=name}await saveCategories(type,items)};
async function saveCategories(type,items){try{await setDoc(settingsRef,{[type==="income"?"incomeCategories":type==="expense"?"expenseCategories":"transferCategories"]:items,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid},{merge:true});toast("Kasa kategorileri güncellendi.")}catch(error){console.error(error);toast("Kategoriler güncellenemedi.")}}

function isFinanceDayClosed(date){return financeDays.some(x=>x.id===date&&x.locked===true)}
function isAdisyonDayClosed(date){return closings.some(x=>x.businessDate===date)}
function isFinanceLocked(date){return date<FINANCE_START_DATE||isFinanceDayClosed(date)}
function canEditSelectedDate(){return selectedDate>=FINANCE_START_DATE&&selectedDate<=today()&&!isFinanceLocked(selectedDate)}
function showFinanceDayEndWarning(){$("financeDayEndWarningTitle").textContent="Önce gün sonunu kapatın";if($("financeCloseDialog").open)$("financeCloseDialog").close();$("financeDayEndWarningText").textContent=`${formatBusinessDate(selectedDate)} için Adisyon bölümündeki gün sonu henüz kapatılmadı. Önce açık adisyonları ve aktif demlikleri tamamlayıp “Günü Kapat” işlemini yapın.`;$("financeDayEndWarningDialog").showModal()}
async function pendingInternalConsumption(date){if(hasLocalPendingInternalConsumption(date))return true;const snap=await getDoc(doc(db,"adminInternalConsumptionDrafts",date));return hasPendingInternalConsumptionDraft(snap.data())}
function showFinanceInternalWarning(){if($("financeCloseDialog").open)$("financeCloseDialog").close();$("financeDayEndWarningTitle").textContent="Dahili tüketim bekliyor";$("financeDayEndWarningText").textContent="Bu tarihte dahili tüketim için bekleyen ürünler var. Önce Adisyon bölümünden stoktan düşün veya listeyi temizleyin.";$("financeDayEndWarningDialog").showModal()}
async function openFinanceClose(){if(isFinanceLocked(selectedDate))return toast("Bu finans günü zaten kapalı.");if(!isAdisyonDayClosed(selectedDate))return showFinanceDayEndWarning();try{if(await pendingInternalConsumption(selectedDate))return showFinanceInternalWarning()}catch(error){console.error(error);return toast("Dahili tüketim kontrol edilemedi. Bağlantıyı kontrol edin.")} $("financeCloseText").textContent=`${formatBusinessDate(selectedDate)} kapatıldıktan sonra bu tarihe gelir, gider veya aktarım eklenemez; kayıtlar değiştirilemez ve silinemez. İşlem ayrıntıları geçmiş günlerde görünmeye devam eder.`;$("financeCloseDialog").showModal()}
async function closeFinanceDay(){if(isFinanceLocked(selectedDate))return;if(!isAdisyonDayClosed(selectedDate))return showFinanceDayEndWarning();try{const date=selectedDate;if(hasLocalPendingInternalConsumption(date))return showFinanceInternalWarning();await runTransaction(db,async tx=>{const draft=await tx.get(doc(db,"adminInternalConsumptionDrafts",date)),financeRef=doc(db,"adminFinanceDays",date),existing=await tx.get(financeRef);if(hasPendingInternalConsumptionDraft(draft.data()))throw new Error("pending-internal-consumption");if(existing.exists())throw new Error("already-closed");tx.set(financeRef,{businessDate:date,locked:true,closedAtMs:Date.now(),closedAt:serverTimestamp(),closedBy:auth.currentUser.uid})});$("financeCloseDialog").close();toast(`${formatBusinessDate(date)} finans kayıtları kapatıldı.`)}catch(error){console.error(error);if(error.message==="pending-internal-consumption")showFinanceInternalWarning();else toast(error.message==="already-closed"?"Bu finans günü zaten kapalı.":"Finans günü kapatılamadı. Bağlantıyı ve Firebase kurallarını kontrol edin.")}}

function openReport(){$("reportMonth").value=selectedDate.slice(0,7);renderReport();$("reportContent").scrollTop=0;$("reportDialog").showModal();requestAnimationFrame(updateReportScroll)}
function currentAccountReport(month){let cash=0,bank=0,card=0;for(const sale of sales){if(sale.reversed===true||sale.cancelled===true)continue;const date=String(sale.businessDate||"");if(!date.startsWith(month)||sale.recordType!=="current-account-payment")continue;cash+=number(sale.cashAmount);bank+=number(sale.transferAmount);card+=number(sale.cardAmount)}return{receivable:currentAccountReceivableAtMonthEnd(month),cash,bank,card}}
function currentAccountReceivableAtMonthEnd(month){if(month===today().slice(0,7))return Math.max(0,currentAccounts.reduce((sum,account)=>sum+number(account.balance),0));const monthEnd=`${month}-31`,latestByAccount=new Map;for(const movement of currentAccountMovements){if(movement.reversed===true)continue;const date=String(movement.businessDate||"");if(!date||date>monthEnd||!movement.accountId)continue;const order=`${date}|${String(number(movement.createdAtMs)).padStart(16,"0")}|${movement.id||""}`,current=latestByAccount.get(movement.accountId);if(!current||order>current.order)latestByAccount.set(movement.accountId,{order,balance:Math.max(0,number(movement.balanceAfter))})}return[...latestByAccount.values()].reduce((sum,item)=>sum+item.balance,0)}

let reportDragOffset=null;
function updateReportScroll(){
 const content=$("reportContent"),track=$("reportScrollTrack"),thumb=$("reportScrollThumb");
 const maximum=Math.max(0,content.scrollHeight-content.clientHeight),height=track.clientHeight;
 const thumbHeight=maximum?Math.min(height,Math.max(24,Math.round(height*content.clientHeight/content.scrollHeight))):height;
 thumb.style.height=`${thumbHeight}px`;
 thumb.style.transform=`translateY(${maximum?(height-thumbHeight)*content.scrollTop/maximum:0}px)`;
 track.setAttribute("aria-valuenow",String(maximum?Math.round(100*content.scrollTop/maximum):0));
 track.setAttribute("aria-disabled",String(!maximum));
 $("reportScrollUp").disabled=content.scrollTop<=0;
 $("reportScrollDown").disabled=content.scrollTop>=maximum-1;
}
function scrollReport(amount){$("reportContent").scrollBy({top:amount,behavior:"smooth"})}
function setReportScrollFromPointer(event,offset){
 const content=$("reportContent"),track=$("reportScrollTrack"),thumb=$("reportScrollThumb"),rect=track.getBoundingClientRect();
 const travel=rect.height-thumb.offsetHeight,maximum=content.scrollHeight-content.clientHeight;
 if(travel>0&&maximum>0)content.scrollTop=Math.max(0,Math.min(1,(event.clientY-rect.top-offset)/travel))*maximum;
}
function startReportScrollDrag(event){
 const track=$("reportScrollTrack"),thumb=$("reportScrollThumb"),rect=thumb.getBoundingClientRect();
 reportDragOffset=event.clientY>=rect.top&&event.clientY<=rect.bottom?event.clientY-rect.top:thumb.offsetHeight/2;
 track.setPointerCapture(event.pointerId);setReportScrollFromPointer(event,reportDragOffset);event.preventDefault();
}
function moveReportScrollDrag(event){if(reportDragOffset!==null)setReportScrollFromPointer(event,reportDragOffset)}
function stopReportScrollDrag(){reportDragOffset=null}
function reportScrollKey(event){
 const steps={ArrowUp:-70,ArrowDown:70,PageUp:-400,PageDown:400,Home:-Infinity,End:Infinity};
 if(!(event.key in steps))return;
 event.preventDefault();const amount=steps[event.key];
 if(Number.isFinite(amount))scrollReport(amount);else $("reportContent").scrollTop=amount<0?0:$("reportContent").scrollHeight;
}
function reportData(){let month=$("reportMonth").value||today().slice(0,7);if(month<"2026-08")month="2026-08";$("reportMonth").value=month;const rows=allMovements().filter(m=>m.businessDate?.startsWith(month)),totals=dayTotals(rows),balances=balancesThrough(`${month}-31`),currentAccount=currentAccountReport(month),totalIncome=totals.cashIncome+totals.bankIncome+totals.cardIncome,profitLoss=totalIncome-totals.expense,incomes=[["Nakit Gelir",totals.cashIncome],["Banka Geliri",totals.bankIncome],["Kart / POS Geliri",totals.cardIncome]].filter(([,value])=>Math.abs(value)>.001);incomes.push(["Cari Hesaptan Gelen Nakit",currentAccount.cash],["Cari Hesaptan Gelen Havale",currentAccount.bank],["Cari Hesaptan Gelen Kart",currentAccount.card]);return{month,rows,totals,balances,currentAccount,totalIncome,profitLoss,expenses:groupAmounts(rows.filter(m=>m.type==="expense"),m=>m.category||"Diğer"),incomes,products:groupProducts(closings.filter(c=>c.businessDate>=HISTORY_START_DATE&&c.businessDate?.startsWith(month)))}}
function reportResult(d){const positive=d.profitLoss>0.001,negative=d.profitLoss<-.001,label=positive?"Kârınız":negative?"Zararınız":"Kâr / Zarar",cls=positive?"profit":negative?"loss":"neutral";return`<div class="report-result ${cls}"><span>${label}</span><b>${money(Math.abs(d.profitLoss))}</b></div>`}
function renderReport(){const d=reportData();$("reportContent").innerHTML=`<div class="report-totals"><div class="report-stat"><span>Nakit Gelir</span><b>${money(d.totals.cashIncome)}</b></div><div class="report-stat"><span>Banka Geliri</span><b>${money(d.totals.bankIncome)}</b></div><div class="report-stat"><span>Kart / POS Geliri</span><b>${money(d.totals.cardIncome)}</b></div><div class="report-stat total-income-stat"><span>Toplam Gelir</span><b>${money(d.totalIncome)}</b></div><div class="report-stat"><span>Toplam Gider</span><b>${money(d.totals.expense)}</b></div></div><div class="report-accounts"><div class="report-stat"><span>Ay Sonu Nakit</span><b>${money(d.balances.cash)}</b></div><div class="report-stat"><span>Ay Sonu Banka</span><b>${money(d.balances.bank)}</b></div><div class="report-stat"><span>Ay Sonu Kart / POS</span><b>${money(d.balances.card)}</b></div><div class="report-stat"><span>Kredi Kartı Genel Borç</span><b>${money(Math.max(0,d.balances.cardDebt))}</b></div><div class="report-stat current-account-balance"><span>Cari Hesap Toplam Alacak</span><b>${money(d.currentAccount.receivable)}</b></div></div>${reportResult(d)}${reportSection("Gelirler",d.incomes,"Bu ay gelir yok.")}${reportSection("Giderler",d.expenses,"Bu ay gider yok.")}${reportSection("Banka kredisi taksit ödemeleri (gider toplamından ayrı)",groupAmounts(d.rows.filter(m=>m.type==="transfer"&&m.toAccount==="bankLoan"),m=>m.description||"Banka kredisi"),"Bu ay kredi taksit ödemesi yok.")}${reportSection("Birikime Yatırma (gelir-giderden ayrı)",groupAmounts(d.rows.filter(m=>m.source==="savings"&&m.fromAccount!=="savings"),m=>m.category),"Bu ay birikime yatırma yok.")}${reportSection("Birikimden TL Hesabına Dönüş (gelir-giderden ayrı)",groupAmounts(d.rows.filter(m=>m.source==="savings"&&m.fromAccount==="savings"),m=>m.category),"Bu ay bozdurma yok.")}${productSection(d.products)}`}
function printReport(){const d=reportData(),title=monthName(d.month),content=$("reportContent").innerHTML,w=window.open("","_blank","width=900,height=700");if(!w)return toast("PDF penceresi açılamadı.");w.document.write(`<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>${esc(title)} Kasa Raporu</title><style>body{font-family:Arial;color:#352522;padding:28px}header{display:flex;align-items:center;border-bottom:3px solid #7d1b24;padding-bottom:14px;margin-bottom:18px}header img{width:72px;height:72px;object-fit:contain;margin-right:14px}h1,h2,h3,p{margin:0}header p{color:#777;margin-top:4px}.report-totals,.report-accounts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.report-stat{border:1px solid #ddd;border-radius:8px;padding:10px}.report-stat span,.report-stat b{display:block}.report-stat span{font-size:11px;color:#777}.report-stat b{margin-top:5px}.current-account-balance b{color:#b3262d}.total-income-stat b{color:#315f89}.report-result{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 0;padding:12px 14px;border:1px solid #ddd;border-radius:8px;font-weight:700}.report-result.profit{border-color:#b8d8c5;background:#eef8f2;color:#207245}.report-result.loss{border-color:#e5b9bd;background:#fff0f1;color:#b3262d}.report-result.neutral{background:#f4f1ed;color:#6f6460}.report-section{margin-top:18px}.report-row{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding:7px 0;font-size:12px}.empty{color:#777}button{display:none}@media print{body{padding:0}}</style></head><body><header><img src="../assets/images/logo.png"><div><h1>Fatih Çay Evi</h1><h2>${esc(title)} Kasa Raporu</h2><p>Oluşturulma: ${new Date().toLocaleString("tr-TR")}</p></div></header>${content}<script>setTimeout(()=>window.print(),500)<\/script></body></html>`);w.document.close()}
function groupAmounts(rows,key){const map=new Map;for(const row of rows){const name=key(row);map.set(name,(map.get(name)||0)+number(row.amount))}return[...map].sort((a,b)=>b[1]-a[1])}function groupProducts(items){const map=new Map;for(const c of items)for(const p of c.products||[]){const name=p.name||"Ürün",v=map.get(name)||{quantity:0,total:0};v.quantity+=number(p.quantity);v.total+=number(p.total);map.set(name,v)}return[...map].sort((a,b)=>b[1].quantity-a[1].quantity)}function reportSection(title,rows,empty){return`<section class="report-section"><h3>${title}</h3>${rows.length?rows.map(([name,total])=>`<div class="report-row"><span>${esc(name)}</span><b>${money(total)}</b></div>`).join(""):`<p class="empty">${empty}</p>`}</section>`}function productSection(rows){return`<section class="report-section"><h3>Ürün Satışları</h3>${rows.length?rows.map(([name,v])=>`<div class="report-row"><span>${esc(name)}</span><b>${v.quantity} adet <small>• ${money(v.total)}</small></b></div>`).join(""):'<p class="empty">Bu ay kapatılmış ürün satışı yok.</p>'}</section>`}

function sortMovements(a,b){return number(b.createdAtMs)-number(a.createdAtMs)||String(b.id).localeCompare(String(a.id))}function movementIcon(m){return m.automatic?"fa-lock":m.type==="income"?"fa-arrow-trend-up":m.type==="expense"?"fa-arrow-trend-down":"fa-right-left"}function sign(m){return m.type==="income"?"+":m.type==="expense"?"−":"↔"}function typeName(t){return t==="income"?"Gelir":t==="expense"?"Gider":"Aktarım"}function accountText(m){const n={cash:"Nakit",bank:"Banka Havalesi",card:"Kart / POS",creditCard:"Kredi Kartı",bankLoan:"Banka Kredisi",savings:"Birikim"};return m.type==="transfer"?`${n[m.fromAccount]||""} → ${n[m.toAccount]||""}`:n[m.account]||""}function number(v){return Number(v)||0}function money(v){return new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY"}).format(number(v))}function today(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Istanbul"}).format(new Date())}function shiftDate(v,n){const d=new Date(`${v}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}function dateObject(v){return new Date(`${v}T12:00:00Z`)}function formatBusinessDate(v){return new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"numeric",timeZone:"UTC"}).format(dateObject(v))}function dayName(v){return new Intl.DateTimeFormat("tr-TR",{weekday:"long",timeZone:"UTC"}).format(dateObject(v))}function monthName(v){return new Intl.DateTimeFormat("tr-TR",{month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(`${v}-01T12:00:00Z`))}function formatTime(ms){return ms?new Intl.DateTimeFormat("tr-TR",{hour:"2-digit",minute:"2-digit",timeZone:"Europe/Istanbul"}).format(new Date(ms)):""}function updateClock(){const n=new Date();$("currentTime").textContent=n.toLocaleTimeString("tr-TR",{hour:"2-digit",minute:"2-digit"});$("currentDate").textContent=n.toLocaleDateString("tr-TR",{day:"2-digit",month:"2-digit",year:"2-digit"})}function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}function toast(message){clearTimeout(toastTimer);$("toast").textContent=message;$("toast").classList.add("show");toastTimer=setTimeout(()=>$("toast").classList.remove("show"),3000)}
